
/* ===== Pestaña Niñas: almuerzos, meriendas y horarios escolares ===== */
(()=>{
let open=false,loading=false,weekStart='',plans=[],items=[],subjects=[],schedules=[],child='Adri',schoolDay=0;
const DAYS=['Lunes','Martes','Miércoles','Jueves','Viernes'];
const SHORT=['L','M','X','J','V'];
const SLOTS=['09:30–10:30','10:30–11:30','11:30–12:00','12:00–13:00','13:00–15:10','15:10–15:55','15:55–16:40','16:40–17:10'];
const e=s=>esc(s), add=(iso,n)=>{let d=new Date(iso+'T12:00');d.setDate(d.getDate()+n);return d.toLocaleDateString('en-CA')};
function monday(){let d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return d.toLocaleDateString('en-CA')}
function title(){let a=new Date(weekStart+'T12:00'),b=new Date(add(weekStart,4)+'T12:00');return `${a.toLocaleDateString('es-ES',{day:'numeric',month:'short'})} – ${b.toLocaleDateString('es-ES',{day:'numeric',month:'short'})}`}
function style(){if(document.querySelector('#girls-style'))return;let x=document.createElement('style');x.id='girls-style';x.textContent=`
nav button[data-girls-tab] .girls-nav-icon{display:block!important;visibility:visible!important;opacity:1!important;width:auto!important;height:auto!important;overflow:visible!important;font-family:Apple Color Emoji,Segoe UI Emoji,Noto Color Emoji,sans-serif!important;font-size:21px!important;line-height:1!important;color:initial!important}nav{display:grid!important;grid-template-columns:repeat(7,minmax(0,1fr))!important;gap:0!important}nav button{min-width:0!important;padding:7px 2px!important}nav button i{font-size:20px!important}nav button span{font-size:10px!important;white-space:nowrap}@media(max-width:370px){nav button i{font-size:18px!important}nav button span{font-size:9px!important}}.girls-page{padding:12px 12px 92px}.girls-head{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:12px}.girls-head h1{margin:0;font-size:22px}.girls-card{background:#fff;border:1px solid #efd5dd;border-radius:16px;padding:12px;margin-bottom:12px;box-shadow:0 4px 14px rgba(92,48,62,.06)}.girls-card h2{margin:0 0 10px;font-size:17px}.girls-week{display:flex;align-items:center;justify-content:space-between;gap:7px;margin-bottom:10px}.girls-week button,.girls-tools button,.girls-days button,.girls-child button{border:0;border-radius:10px;background:#f8e3e9;color:#6f2940;padding:8px 10px}.girls-week b{font-size:13px;text-align:center}.girls-plan{display:grid;gap:8px}.girls-row{display:grid;grid-template-columns:66px 1fr 1fr;gap:7px;align-items:center}.girls-row>strong{font-size:12px}.girls-label{font-size:10px;color:#806d73;text-transform:uppercase}.girls-choice{min-width:0;border:1px solid #ead2d9;border-radius:10px;background:#fff;padding:9px 7px;text-align:left;font-size:12px;color:#44353a}.girls-choice:active{background:#f8dce5}.girls-tools{display:flex;justify-content:flex-end;margin-top:10px}.girls-days,.girls-child{display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin-bottom:10px}.girls-child{grid-template-columns:1fr 1fr}.girls-child button{display:flex;align-items:center;justify-content:center;gap:8px;min-height:54px}.girls-child button img{width:38px;height:38px;flex:0 0 38px;border-radius:50%;object-fit:cover;background:#fff;border:2px solid transparent}.girls-child button span{font-size:13px}.girls-days button.active,.girls-child button.active{background:#d96f8d;color:white;font-weight:700}.girls-child button.active img{border-color:#fff;box-shadow:0 0 0 2px #d96f8d}.school-grid{display:grid;grid-template-columns:92px 1fr;gap:7px;align-items:center}.school-grid label{font-size:12px;font-weight:700}.school-grid .school-choice{width:100%;min-width:0;border:1px solid #ead2d9;border-radius:9px;padding:9px;background:#fff;text-align:left;font-size:13px;color:#44353a}.school-grid .school-choice:active{background:#f8dce5}.girls-overlay{position:fixed;inset:0;z-index:10020;background:rgba(43,29,34,.38);display:flex;align-items:center;justify-content:center;padding:16px}.girls-popup{width:min(92vw,390px);max-height:75vh;display:flex;flex-direction:column;background:#fff;border-radius:16px;overflow:hidden}.girls-popup-head{display:flex;align-items:center;justify-content:space-between;padding:12px;border-bottom:1px solid #efd5dd}.girls-popup-head h3{margin:0;font-size:17px}.girls-popup-head button{border:0;background:#f8e3e9;border-radius:50%;width:30px;height:30px}.girls-list{overflow:auto;padding:8px}.girls-list-row{display:grid;grid-template-columns:1fr 36px;gap:7px;margin-bottom:6px}.girls-list-row button{border:0;border-radius:9px;padding:10px;text-align:left;background:#fdf5f7}.girls-list-row .delete{color:#a12f50;text-align:center}.girls-add{display:flex;gap:7px;padding:10px;border-top:1px solid #efd5dd}.girls-add input{flex:1;min-width:0;border:1px solid #e4cbd3;border-radius:9px;padding:9px}.girls-add button{border:0;border-radius:9px;background:#d96f8d;color:white;padding:9px 12px}@media(max-width:390px){.girls-row{grid-template-columns:58px 1fr 1fr}.girls-choice{font-size:11px;padding:8px 5px}.school-grid{grid-template-columns:88px 1fr}}`;document.head.appendChild(x)}
async function load(){loading=true;weekStart=weekStart||monday();let fid=profile?.family_id;if(!fid){loading=false;return false}let [a,b,c,d]=await Promise.all([sb.from('girls_snack_items').select('*').eq('family_id',fid).eq('active',true).order('sort_order'),sb.from('girls_week_plans').select('*').eq('family_id',fid).eq('week_start',weekStart),sb.from('girls_school_schedule').select('*').eq('family_id',fid),sb.from('girls_school_subjects').select('*').eq('family_id',fid).eq('active',true).order('sort_order')]);loading=false;if(a.error||b.error||c.error||d.error){alert('Falta crear las tablas de la pestaña Niñas. Ejecuta primero el SQL incluido.');return false}items=a.data||[];plans=b.data||[];schedules=c.data||[];subjects=d.data||[];return true}
function itemName(id){return items.find(x=>String(x.id)===String(id))?.name||'— Elegir —'}
function page(){if(loading)return `<section class="girls-page"><div class="girls-card">Cargando…</div></section>`;return `<section class="girls-page"><div class="nv-page-heading"><span class="nv-page-heading-icon">👧</span><div class="nv-page-heading-text"><h1>Niñas</h1><p>Almuerzos, meriendas y horarios del cole</p></div></div><section class="girls-card"><h2>🥪 Almuerzos y meriendas</h2><div class="girls-week"><button data-gweek="-7">‹</button><b>${title()}</b><button data-gweek="7">›</button></div><div class="girls-plan"><div class="girls-row"><span></span><span class="girls-label">Almuerzo</span><span class="girls-label">Merienda</span></div>${DAYS.map((d,i)=>{let p=plans.find(x=>x.day_index===i)||{};return `<div class="girls-row"><strong>${d}</strong><button class="girls-choice" data-pick="lunch" data-day="${i}">${e(itemName(p.lunch_item_id))}</button><button class="girls-choice" data-pick="snack" data-day="${i}">${e(itemName(p.snack_item_id))}</button></div>`}).join('')}</div><div class="girls-tools"><button data-manage-snacks>⚙️ Gestionar lista</button></div></section><section class="girls-card"><h2>🎒 Horario del cole</h2><div class="girls-child"><button data-child="Adri" class="${child==='Adri'?'active':''}"><img src="data:image/jpeg;base64," alt=""><span>Adri</span></button><button data-child="Siena" class="${child==='Siena'?'active':''}"><img src="data:image/jpeg;base64," alt=""><span>Siena</span></button></div><div class="girls-days">${SHORT.map((d,i)=>`<button data-school-day="${i}" class="${schoolDay===i?'active':''}">${d}</button>`).join('')}</div><div class="school-grid">${SLOTS.map((slot,i)=>{let r=schedules.find(x=>x.child_name===child&&x.day_index===schoolDay&&x.slot_index===i);return `<label>${slot}</label><button class="school-choice" data-school-pick="${i}">${e(r?.subject||'— Elegir —')}</button>`}).join('')}</div><div class="girls-tools"><button data-manage-subjects>⚙️ Gestionar asignaturas</button></div></section></section>`}
function render(){style();let v=document.querySelector('#view');if(!v||!open)return;v.innerHTML=page();bind();document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));document.querySelector('[data-girls-tab]')?.classList.add('active');scrollTo(0,0)}
function bind(){document.querySelectorAll('[data-gweek]').forEach(b=>b.onclick=()=>{weekStart=add(weekStart,+b.dataset.gweek);load()});document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>picker(+b.dataset.day,b.dataset.pick));document.querySelector('[data-manage-snacks]')?.addEventListener('click',()=>picker(null,null,true));document.querySelectorAll('[data-child]').forEach(b=>b.onclick=()=>{child=b.dataset.child;render()});document.querySelectorAll('[data-school-day]').forEach(b=>b.onclick=()=>{schoolDay=+b.dataset.schoolDay;render()});document.querySelectorAll('[data-school-pick]').forEach(b=>b.onclick=()=>subjectPicker(+b.dataset.schoolPick));document.querySelector('[data-manage-subjects]')?.addEventListener('click',()=>subjectPicker(null,true))}
function picker(day,type,manage=false){let old=document.querySelector('.girls-overlay');if(old)old.remove();let box=document.createElement('div');box.className='girls-overlay';box.innerHTML=`<div class="girls-popup"><div class="girls-popup-head"><h3>${manage?'Lista de almuerzos y meriendas':type==='lunch'?'Elegir almuerzo':'Elegir merienda'}</h3><button data-close-girls>×</button></div><div class="girls-list">${manage?'':`<div class="girls-list-row"><button data-snack-choice="">— Sin configurar —</button><span></span></div>`}${items.map(x=>`<div class="girls-list-row"><button ${manage?'disabled':''} data-snack-choice="${x.id}">${e(x.name)}</button>${manage?`<button class="delete" data-delete-snack="${x.id}">🗑️</button>`:'<span></span>'}</div>`).join('')}</div>${manage?`<form class="girls-add"><input name="name" placeholder="Nueva opción" required><button>Añadir</button></form>`:''}</div>`;document.body.appendChild(box);document.body.style.overflow='hidden';let close=()=>{box.remove();document.body.style.overflow=''};box.querySelector('[data-close-girls]').onclick=close;box.addEventListener('click',x=>{if(x.target===box)close()});box.querySelectorAll('[data-snack-choice]').forEach(b=>b.onclick=async()=>{await savePlan(day,type,b.dataset.snackChoice||null);close()});box.querySelector('.girls-add')?.addEventListener('submit',async ev=>{ev.preventDefault();let name=new FormData(ev.target).get('name').trim();if(!name)return;let existing=await sb.from('girls_snack_items').select('*').eq('family_id',profile.family_id).ilike('name',name).maybeSingle();let r=existing.data?await sb.from('girls_snack_items').update({active:true}).eq('id',existing.data.id).select().single():await sb.from('girls_snack_items').insert({family_id:profile.family_id,name,active:true,sort_order:items.length,created_by:session.user.id}).select().single();if(r.error)return alert('No se ha podido añadir.');items.push(r.data);close();picker(null,null,true);render()});box.querySelectorAll('[data-delete-snack]').forEach(b=>b.onclick=async()=>{let r=await sb.from('girls_snack_items').update({active:false}).eq('id',b.dataset.deleteSnack).eq('family_id',profile.family_id);if(r.error)return alert('No se ha podido eliminar.');items=items.filter(x=>String(x.id)!==b.dataset.deleteSnack);close();picker(null,null,true);render()})}
async function savePlan(day,type,id){let p=plans.find(x=>x.day_index===day)||{family_id:profile.family_id,week_start:weekStart,day_index:day,lunch_item_id:null,snack_item_id:null};p[type==='lunch'?'lunch_item_id':'snack_item_id']=id?+id:null;let r=await sb.from('girls_week_plans').upsert({...p,updated_by:session.user.id,updated_at:new Date().toISOString()},{onConflict:'family_id,week_start,day_index'}).select().single();if(r.error)return alert('No se ha podido guardar.');let i=plans.findIndex(x=>x.day_index===day);if(i<0)plans.push(r.data);else plans[i]=r.data;render()}
function subjectPicker(slot,manage=false){let old=document.querySelector('.girls-overlay');if(old)old.remove();let box=document.createElement('div');box.className='girls-overlay';box.innerHTML=`<div class="girls-popup"><div class="girls-popup-head"><h3>${manage?'Lista de asignaturas':'Elegir asignatura'}</h3><button data-close-girls>×</button></div><div class="girls-list">${manage?'':`<div class="girls-list-row"><button data-subject-choice="">— Sin configurar —</button><span></span></div>`}${subjects.map(x=>`<div class="girls-list-row"><button ${manage?'disabled':''} data-subject-choice="${e(x.name)}">${e(x.name)}</button>${manage?`<button class="delete" data-delete-subject="${x.id}">🗑️</button>`:'<span></span>'}</div>`).join('')}</div>${manage?`<form class="girls-add"><input name="name" placeholder="Nueva asignatura" required><button>Añadir</button></form>`:''}</div>`;document.body.appendChild(box);document.body.style.overflow='hidden';let close=()=>{box.remove();document.body.style.overflow=''};box.querySelector('[data-close-girls]').onclick=close;box.addEventListener('click',x=>{if(x.target===box)close()});box.querySelectorAll('[data-subject-choice]').forEach(b=>b.onclick=async()=>{await saveSchool(slot,b.dataset.subjectChoice||'');close();render()});box.querySelector('.girls-add')?.addEventListener('submit',async ev=>{ev.preventDefault();let name=String(new FormData(ev.target).get('name')||'').trim().replace(/\s+/g,' ');if(!name)return;let existing=await sb.from('girls_school_subjects').select('*').eq('family_id',profile.family_id).ilike('name',name).maybeSingle();let r=existing.data?await sb.from('girls_school_subjects').update({active:true}).eq('id',existing.data.id).select().single():await sb.from('girls_school_subjects').insert({family_id:profile.family_id,name,active:true,sort_order:subjects.length,created_by:session.user.id}).select().single();if(r.error)return alert('No se ha podido añadir la asignatura.');subjects=subjects.filter(x=>String(x.id)!==String(r.data.id));subjects.push(r.data);close();subjectPicker(null,true)});box.querySelectorAll('[data-delete-subject]').forEach(b=>b.onclick=async()=>{let r=await sb.from('girls_school_subjects').update({active:false}).eq('id',b.dataset.deleteSubject).eq('family_id',profile.family_id);if(r.error)return alert('No se ha podido eliminar la asignatura.');subjects=subjects.filter(x=>String(x.id)!==b.dataset.deleteSubject);close();subjectPicker(null,true)})}
async function saveSchool(slot,value){let row={family_id:profile.family_id,child_name:child,day_index:schoolDay,slot_index:slot,subject:value.trim(),updated_by:session.user.id,updated_at:new Date().toISOString()};let r=await sb.from('girls_school_schedule').upsert(row,{onConflict:'family_id,child_name,day_index,slot_index'}).select().single();if(r.error)return alert('No se ha podido guardar el horario.');let i=schedules.findIndex(x=>x.child_name===child&&x.day_index===schoolDay&&x.slot_index===slot);if(i<0)schedules.push(r.data);else schedules[i]=r.data}
async function openGirls(){if(open&&document.querySelector('.girls-page'))return;open=true;weekStart=weekStart||monday();if(await load())render()}
function install(){let nav=document.querySelector('nav');if(!nav)return;let b=nav.querySelector('[data-girls-tab]');if(b){b.innerHTML='<i class="girls-nav-icon" aria-hidden="true">👧</i><span>Niñas</span>';b.onclick=e=>{e.preventDefault();e.stopPropagation();openGirls()}}document.querySelectorAll('nav button:not([data-girls-tab])').forEach(x=>{if(!x.dataset.girlsWired){x.dataset.girlsWired='1';x.addEventListener('click',()=>open=false)}});}
window.addEventListener('nv-open-girls',openGirls);window.addEventListener('nv-close-girls',()=>{open=false});
let busy=false;new MutationObserver(()=>{if(busy)return;busy=true;requestAnimationFrame(()=>{install();busy=false})}).observe(document.documentElement,{childList:true,subtree:true});install();
})();
